from pathlib import Path
import csv,json,shutil,subprocess,sys,tempfile

root=Path(__file__).resolve().parents[1]
results=root/'Proyecto/evaluation/results'
gt_csv=root/'Proyecto/evaluation/gt/BAR-ATH_possession_gt_public.csv'
datasets={}
for key,filename,title in [('baseline','primera_prueba.csv','Baseline smooth50'),('v1','algoritmo_v1.csv','Algoritmo v1 · pase con toque real o control > 1 s + veto del portero + D si no hay balón'),('viterbi','v1_viterbi.csv','Algoritmo Viterbi (ccruz) · evidencia de control + balón muerto + Viterbi H/A/D'),('gt','../gt/BAR-ATH_possession_gt_public.csv','Ground truth público (5 min)')]:
    with (results/filename).open(newline='') as f:
        rows=list(csv.DictReader(f))
    assert len(rows)==199319 and all(int(r['frame'])==i and r['label'] in 'HADX' for i,r in enumerate(rows))
    segments=[]
    for i,r in enumerate(rows):
        if not segments or r['label']!=segments[-1][2]:segments.append([i,i+1,r['label']])
        else:segments[-1][1]=i+1
    assert sum(b-a for a,b,l in segments)==199319
    datasets[key]={'segments':segments,'filename':filename,'title':title}
baselines={'baseline':datasets['baseline']}
for key,filename,title in [('smooth50','baseline_smooth50.csv','Baseline smooth50'),('raw','baseline_raw.csv','Baseline sin suavizar'),('smooth25','baseline_smooth25.csv','Baseline smooth25'),('smooth125','baseline_smooth125.csv','Baseline smooth125')]:
    with (root/'Proyecto/evaluation/results'/filename).open(newline='') as f:
        rows=list(csv.DictReader(f))
    assert len(rows)==199319 and all(int(r['frame'])==i and r['label'] in 'HADX' for i,r in enumerate(rows))
    segments=[]
    for i,r in enumerate(rows):
        if not segments or r['label']!=segments[-1][2]:segments.append([i,i+1,r['label']])
        else:segments[-1][1]=i+1
    baselines[key]={'segments':segments,'filename':filename,'title':title}
# métricas oficiales sobre los 5 minutos públicos (mismo script que el scoreboard)
metrics={}
with tempfile.TemporaryDirectory() as tmp:
    sub,out_eval=Path(tmp)/'sub',Path(tmp)/'eval'
    sub.mkdir()
    for key in ('baseline','v1','viterbi'):
        shutil.copy(results/datasets[key]['filename'],sub/(key+'.csv'))
    subprocess.run([sys.executable,'run_evaluation.py','--results',str(sub),'--out',str(out_eval),'--no-detail'],cwd=root/'Proyecto/evaluation',check=True,capture_output=True)
    with (out_eval/'scoreboard.csv').open(newline='') as f:
        for r in csv.DictReader(f):
            metrics[r['submission']]={k:r[k] for k in ('macro_f1','spell_f1_mean','kappa','accuracy','f1_H','f1_A','f1_D','alive_dead_f1','trans_f1_25','poss','dur','n_gt_spells','gt_mean_spell_duration_s')}
